// Whirlpool – Detail-Reel 9:16. Deterministic, frame-addressed motion graphics:
// window.COMP.seek(n) puts the stage into the exact state of output frame n.
// Footage timing (cuts, slow motion) comes from timeline.js, generated by
// scripts/retime.py from edit.json; one plate per output frame.
//
// Graphics: one 3D card (CardContainer → CardBody → CardItem). The body drifts
// like a hovered card, its items float on their own translateZ layers. On every
// cut the items sink, the card flips over its edge and comes back with the next
// detail.
(() => {
  const { FPS, TOTAL, SHOTS } = window.TIMELINE;
  const params = new URLSearchParams(location.search);
  const PLATE_DIR = params.get('plates') || '../../build/whirlpool/plates';
  const SRC_DIR = `${PLATE_DIR}/../src`;   // graded source frames, written by retime.py

  const ORDER = ['intro', 'B', 'C', 'D', 'E', 'F', 'G'];
  const START = { intro: 0, B: SHOTS.B.start, C: SHOTS.C.start, D: SHOTS.D.start, E: SHOTS.E.start, F: SHOTS.F.start, G: SHOTS.G.start };
  const END_T = TOTAL / FPS;
  const T = {
    build: 0.12,          // card swings in
    float: 0.50,          // items lift off the body
    sink: 0.42,           // items settle back this long before a cut
    flipOut: 0.20,        // card turns edge-on into the cut...
    flipIn: 0.36,         // ...and back out of it with the next detail
  };
  const Z_SCALE = 1.3;    // CardItem translateZ values are given for a 480px card

  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
  const prog = (t, start, dur) => clamp((t - start) / dur);
  const E = {
    outExpo: k => (k >= 1 ? 1 : 1 - Math.pow(2, -10 * k)),
    inCubic: k => k * k * k,
    outCubic: k => 1 - Math.pow(1 - k, 3),
    inOutCubic: k => (k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2),
  };

  const el = {
    plate: $('#plate'), container: $('#container'), body: $('#body'),
    cards: Object.fromEntries($$('.card').map(c => [c.dataset.sec, c])),
  };
  const items = Object.fromEntries(ORDER.map(s => [s, $$('.item', el.cards[s]).map(node => ({
    node,
    z: parseFloat(node.dataset.z || 0) * Z_SCALE,
    x: parseFloat(node.dataset.x || 0) * Z_SCALE,
    rx: parseFloat(node.dataset.rx || 0),
    rz: parseFloat(node.dataset.rz || 0),
  }))]));
  const pics = Object.fromEntries(ORDER.map(s => {
    const [f, x, y, zoom] = el.cards[s].dataset.pic.split(' ').map(Number);
    return [s, { img: $('.pic img', el.cards[s]), box: $('.pic', el.cards[s]), f, x, y, zoom }];
  }));

  const secAt = t => ORDER.reduce((cur, s) => (t >= START[s] ? s : cur), 'intro');

  function render(n) {
    const t = n / FPS;
    const sec = secAt(t);
    const si = ORDER.indexOf(sec);
    const next = ORDER[si + 1];
    const s0 = START[sec], s1 = next ? START[next] : END_T;

    ORDER.forEach(s => { el.cards[s].style.display = s === sec ? '' : 'none'; });

    // Body: swing-in, hover drift, flip on the cuts.
    const kb = E.outExpo(prog(t, T.build, 0.9));
    const flipIn = si === 0 ? 0 : -90 * (1 - E.outCubic(prog(t, s0, T.flipIn)));
    const flipOut = next ? 90 * E.inCubic(prog(t, s1 - T.flipOut, T.flipOut)) : 0;
    const rx = 5 * Math.sin((2 * Math.PI * t) / 4.6) + (1 - kb) * -70;
    const ry = 8 * Math.sin((2 * Math.PI * t) / 6.2 + 0.8) + flipIn + flipOut;
    el.body.style.transform = `translateY(${(1 - kb) * 90}px) rotateX(${rx.toFixed(2)}deg) rotateY(${ry.toFixed(2)}deg)`;
    el.body.style.opacity = clamp(kb * 1.6).toFixed(3);

    // Items: float up after the card lands, sink before it flips away.
    const tUp = si === 0 ? T.build + 0.35 : s0 + T.flipIn * 0.55;
    items[sec].forEach((it, i) => {
      const up = E.outExpo(prog(t, tUp + i * 0.06, T.float + 0.2));
      const down = next ? E.inCubic(prog(t, s1 - T.sink, T.sink - T.flipOut)) : 0;
      const k = up * (1 - down);
      it.node.style.transform = `translateX(${(it.x * k).toFixed(1)}px) translateZ(${(it.z * k).toFixed(1)}px) ` +
        `rotateX(${(it.rx * k).toFixed(2)}deg) rotateZ(${(it.rz * k).toFixed(2)}deg)`;
    });

    // Detail picture: source frame framed on the detail, slow push-in.
    const p = pics[sec];
    const s = p.zoom * (1 + 0.07 * prog(t, s0, s1 - s0));
    const cw = p.box.clientWidth, ch = p.box.clientHeight;
    p.img.style.transform = `translate(${(cw / 2 - p.x * s).toFixed(1)}px, ${(ch / 2 - p.y * s).toFixed(1)}px) scale(${s.toFixed(4)})`;
  }

  async function seek(n) {
    const idx = String(Math.min(n, TOTAL - 1)).padStart(4, '0');
    if (el.plate.dataset.idx !== idx) {
      el.plate.src = `${PLATE_DIR}/f${idx}.jpg`;
      await el.plate.decode();
      el.plate.dataset.idx = idx;
    }
    render(n);
  }

  async function init() {
    await Promise.all([400, 500, 600, 700].map(w => document.fonts.load(`${w} 40px Poppins`)));
    await document.fonts.ready;
    await Promise.all(ORDER.map(s => {
      const p = pics[s];
      p.img.src = `${SRC_DIR}/s${String(p.f).padStart(4, '0')}.png`;
      return p.img.decode();
    }));
    await Promise.all($$('.logo img').map(img => img.decode()));
    const t0 = params.get('t');
    await seek(t0 ? Math.round(parseFloat(t0) * FPS) : 0);
  }

  window.COMP = { FPS, TOTAL, seek, ready: init() };
})();
